local PruningSawMaker = {}
local PRODUCTS = {
    iron_pruningsaw = { name = "Železni žaga za obrezovanje", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni žaga za obrezovanje za vrtnarje." },
    bronze_pruningsaw = { name = "Bronast žaga za obrezovanje", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast žaga za obrezovanje za vrtnarje." },
    silver_pruningsaw = { name = "Srebrn žaga za obrezovanje", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn žaga za obrezovanje za vrtnarje." },
    gilded_pruningsaw = { name = "Pozlačen žaga za obrezovanje", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen žaga za obrezovanje za vrtnarje." },
    jewel_set_pruningsaw = { name = "Draguljast žaga za obrezovanje", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast žaga za obrezovanje za vrtnarje." },
    royal_sovereign_pruningsaw = { name = "Kraljevski suveren žaga za obrezovanje", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren žaga za obrezovanje z biseri za krono." },
}
local BUILDINGS = {
    pruningsaw_workshop = { name = "Pruningsaw delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    pruningsaw_house = { name = "Pruningsaw hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_pruningsaw_atelier = { name = "Mojstrski pruningsaw atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_pruningsaw_palace = { name = "Suverena pruningsaw palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
PruningSawMaker.ironStock=18; PruningSawMaker.bronzeStock=14; PruningSawMaker.woodStock=10; PruningSawMaker.leatherStock=8; PruningSawMaker.silverStock=8; PruningSawMaker.goldStock=6; PruningSawMaker.jewelStock=4; PruningSawMaker.pearlStock=4
PruningSawMaker.productStock = {}; PruningSawMaker.buildings = {}; PruningSawMaker.maker = nil; PruningSawMaker.activeMaking = {}; PruningSawMaker.totalProducts = 0; PruningSawMaker.dayTimer = 0
function PruningSawMaker.init() PruningSawMaker.ironStock=18; PruningSawMaker.bronzeStock=14; PruningSawMaker.woodStock=10; PruningSawMaker.leatherStock=8; PruningSawMaker.silverStock=8; PruningSawMaker.goldStock=6; PruningSawMaker.jewelStock=4; PruningSawMaker.pearlStock=4; PruningSawMaker.productStock={}; PruningSawMaker.buildings={}; PruningSawMaker.maker=nil; PruningSawMaker.activeMaking={}; PruningSawMaker.totalProducts=0; PruningSawMaker.dayTimer=0; print("[PruningSawMaker] Royal Pruning Saw Maker System initialized (6 products, 4 buildings)") end
function PruningSawMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; PruningSawMaker.maker={name=n or ("Žagar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Žagar najet: %s (spretnost: %d)",PruningSawMaker.maker.name,s),"success") end; return true end
function PruningSawMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function PruningSawMaker.build(id) local ok,e=PruningSawMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(PruningSawMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function PruningSawMaker.getQualityBonus() local b=0; for _,bd in ipairs(PruningSawMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function PruningSawMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and PruningSawMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and PruningSawMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and PruningSawMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and PruningSawMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and PruningSawMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and PruningSawMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and PruningSawMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and PruningSawMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #PruningSawMaker.buildings==0 then return false,"Potrebna žagarska delavnica" end; if not PruningSawMaker.maker then return false,"Potreben žagar" end; return true end
function PruningSawMaker.make(pt,qty) qty=qty or 1; local ok,e=PruningSawMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then PruningSawMaker.ironStock=PruningSawMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then PruningSawMaker.bronzeStock=PruningSawMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then PruningSawMaker.woodStock=PruningSawMaker.woodStock-d.woodCost*qty end; if d.leatherCost then PruningSawMaker.leatherStock=PruningSawMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then PruningSawMaker.silverStock=PruningSawMaker.silverStock-d.silverCost*qty end; if d.goldCost then PruningSawMaker.goldStock=PruningSawMaker.goldStock-d.goldCost*qty end; if d.jewelCost then PruningSawMaker.jewelStock=PruningSawMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then PruningSawMaker.pearlStock=PruningSawMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if PruningSawMaker.maker then t=math.max(1,t-math.floor(PruningSawMaker.maker.skill/13)) end; table.insert(PruningSawMaker.activeMaking,{id="pruningsaw_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function PruningSawMaker.completeMaking(m) local q=1.0+(PruningSawMaker.getQualityBonus()/100); if PruningSawMaker.maker then q=q+(PruningSawMaker.maker.skill/140) end; q=math.min(2.5,q); PruningSawMaker.productStock[m.productType]=(PruningSawMaker.productStock[m.productType] or 0)+m.quantity; PruningSawMaker.totalProducts=PruningSawMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if PruningSawMaker.maker then PruningSawMaker.maker.itemsMade=PruningSawMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then PruningSawMaker.maker.skill=math.min(100,PruningSawMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Žaga izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"pruningsaw.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function PruningSawMaker.update(dt) if not _G.state then return end; PruningSawMaker.dayTimer=PruningSawMaker.dayTimer+dt; if PruningSawMaker.dayTimer>=30 then PruningSawMaker.dayTimer=0; for i=#PruningSawMaker.activeMaking,1,-1 do local m=PruningSawMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then PruningSawMaker.completeMaking(m); table.remove(PruningSawMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(PruningSawMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if PruningSawMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function PruningSawMaker.getStats() return {ironStock=PruningSawMaker.ironStock,bronzeStock=PruningSawMaker.bronzeStock,woodStock=PruningSawMaker.woodStock,leatherStock=PruningSawMaker.leatherStock,silverStock=PruningSawMaker.silverStock,goldStock=PruningSawMaker.goldStock,jewelStock=PruningSawMaker.jewelStock,pearlStock=PruningSawMaker.pearlStock,productStock=PruningSawMaker.productStock,numBuildings=#PruningSawMaker.buildings,hasMaker=PruningSawMaker.maker~=nil,makerName=PruningSawMaker.maker and PruningSawMaker.maker.name or "—",makerSkill=PruningSawMaker.maker and PruningSawMaker.maker.skill or 0,activeMaking=#PruningSawMaker.activeMaking,totalProducts=PruningSawMaker.totalProducts} end
return PruningSawMaker
